procedure @@proc@@(p_mode in number) is
  l_seen number := 0;
begin
  for r in (select id, @@col@@ from @@tab@@
             where @@col2@@ <> q'[loop; end loop;]') loop
    l_seen := l_seen + 1;
    if r.id > 0 then
      case p_mode
        when 3 then
          delete from @@tab2@@ -- @expect
           where parent_id = r.id;
        else
          null;
      end case;
    end if;
  end loop;
  dbms_output.put_line(l_seen);
end @@proc@@;

procedure @@proc@@ is
  cursor c_src is select id, @@col@@ from @@tab@@;
  l_id number;
  l_val varchar2(50);
begin
  open c_src;
  loop
    fetch c_src into l_id, l_val;
    exit when c_src%notfound;
    begin
      insert into @@tab2@@ (id, @@col@@) -- @expect
      values (l_id, l_val);
    exception
      when dup_val_on_index then
        null;
    end;
  end loop;
  close c_src;
end @@proc@@;

procedure @@proc@@ is
  l_sum number;
begin
  for r in (select id, @@col@@ as qty from @@tab@@) loop
    l_sum := 0;
    for i in 1 .. 4 loop
      l_sum := l_sum + i;
    end loop;
    update @@tab2@@ -- @expect
       set @@col2@@ = l_sum
     where id = r.id;
  end loop;
end @@proc@@;

procedure @@proc@@(p_days in number) is
begin
  <<main>>
  declare
    cursor c_stale is
      select id from @@tab@@ where age_days > p_days;
  begin
    for r in c_stale loop
      update /* mark */ @@tab@@ -- @expect
         set @@col@@ = null
       where id = r.id;
    end loop;
  end main;
end @@proc@@;

procedure @@proc@@(p_n in number) is
  function twice(p_x in number) return number is
  begin
    for i in 1 .. p_x loop
      update @@tab2@@ set @@col@@ = i where id = i;
    end loop;
    return p_x * 2;
  end twice;
begin
  for r in (select id from @@tab@@) loop
    if twice(r.id) > p_n then
      null;
    else
      insert into @@tab2@@ (id) -- @expect
      select r.id from dual;
    end if;
  end loop;
end @@proc@@;

