procedure @@proc@@ is
  l_tot number := 0;
begin
  -- for r in (select 1 from dual) loop update @@tab@@ set x = 1; end loop;
  for r in (select id, @@col@@ as qty from @@tab@@) loop
    case
      when r.qty > 3 then l_tot := l_tot + r.qty;
      else l_tot := l_tot - 1;
    end case;
    if l_tot < 0 then
      l_tot := 0;
    end if;
  end loop;
  update @@tab2@@ set @@col2@@ = l_tot;
end @@proc@@;

procedure @@proc@@ is
  l_msg varchar2(200);
begin
  for r in (select id, @@col@@ from @@tab@@) loop
    l_msg := 'would update @@tab2@@ for ' || r.id;
    dbms_output.put_line(l_msg);
    dbms_output.put_line(q'[delete from @@tab2@@; insert into x;]');
  end loop;
end @@proc@@;

procedure @@proc@@(p_ids in dbms_sql.number_table) is
  l_cnt number := 0;
begin
  for i in reverse p_ids.first .. p_ids.last loop
    delete from @@tab@@ where id = p_ids(i);
    l_cnt := l_cnt + sql%rowcount;
  end loop;
  dbms_output.put_line(l_cnt);
end @@proc@@;

procedure @@proc@@(p_limit in number) is
  l_i number := 0;
begin
  loop
    l_i := l_i + 1;
    -- fetch c_rows into l_row;
    update @@tab@@ set @@col@@ = l_i where id = l_i;
    exit when l_i >= p_limit;
  end loop;
  dbms_output.put_line('fetch next batch');
end @@proc@@;

procedure @@proc@@ is
  l_n number := 0;
begin
  begin
    for r in (select id from @@tab@@) loop
      l_n := l_n + r.id;
    end loop;
  exception
    when dup_val_on_index then
      update @@tab2@@ set @@col@@ = l_n;
  end;
  insert into @@tab2@@ (id) values (l_n);
end @@proc@@;
